mapper.select:
SELECT * FROM (select A.TDY_UNIT_VALUE as tdyUnitValue, A.TDY_UNIT_VALUE_SUM as tdyUnitValueSum, A.CDATE AS cdate, A.YIELD_7 AS yield7, A.TDY_SHARE_AMT AS tdyShareAmt, B.PORTFOLIO_ID as portfolioId, B.PORTFOLIO_NAME as portfolioName FROM BOK_POSITION_PRD A JOIN PTL_PORTFOLIO B ON B.PORTFOLIO_ID=A.FINPROD_ID
and B.PORTFOLIO_ID =#{portfolioId}
and A.CDATE>=TO_DATE(#{startDate},'yyyy-MM-dd')
and TO_DATE(#{endDate},'yyyy-MM-dd')>=A.CDATE
)

SELECT A.PORTFOLIO_ID as portfolioId, A.PORTFOLIO_NAME as portfolioName, B.EFF_DATE as effDate, C.EVAL_INDEX as evalIndex, D.INCOME_TARGET as indexId FROM PTL_PORTFOLIO A JOIN PTL_PORTFOLIO_STGY B --组合策略 ON A.PORTFOLIO_ID=B.PORTFOLIO_ID JOIN PTL_PORTFOLIO_EVAL C ON C.PTL_STGY_ID=B.PTL_STGY_ID JOIN PTL_INCOME_INDEX D ON C.INDEX_ID=D.INDEX_ID
AND A.PORTFOLIO_ID=#{portfolioId}
and B.STRATEGY_ID =#{strategyId}

SELECT A.PORTFOLIO_ID ,A.PORTFOLIO_NAME ,C.BATCH_ID ,D.STRATEGY_NAME FROM PTL_PORTFOLIO A JOIN PTL_PORTFOLIO_STGY B ON A.PORTFOLIO_ID=B.PORTFOLIO_ID JOIN PTL_INV_STRATEGY_DETAIL C ON B.STRATEGY_ID=C.STRATEGY_ID JOIN PTL_INV_STRATEGY D ON B.STRATEGY_ID=D.STRATEGY_ID
A.PORTFOLIO_ID=#{portfolioId}
and D.STRATEGY_ID =#{strategyId}

WITH 组合最新策略 AS (SELECT PTL_STGY_ID ,PORTFOLIO_ID ,STRATEGY_ID ,max(EFF_DATE) AS effDate FROM PTL_PORTFOLIO_STGY WHERE #{endDate}>=nvl2(TO_CHAR(EFF_DATE,'yyyy-mm-dd'),TO_CHAR(EFF_DATE,'yyyy-mm-dd'),'0') AND PORTFOLIO_ID=#{portfolioId} GROUP BY PORTFOLIO_ID,PTL_STGY_ID,STRATEGY_ID) SELECT C.* ,A.effDate ,A.PORTFOLIO_ID ,D.PORTFOLIO_NAME ,B.EVAL_INDEX FROM 组合最新策略 A JOIN PTL_PORTFOLIO_EVAL B ON A.PTL_STGY_ID=B.PTL_STGY_ID
JOIN PTL_INCOME_INDEX C ON B.INDEX_ID=C.INDEX_ID JOIN PTL_PORTFOLIO D ON A.PORTFOLIO_ID=D.PORTFOLIO_ID
and A.STRATEGY_ID =#{strategyId}

SELECT A.* ,B.INT_RATE FROM PTL_INCOME_INDEX_FLOAT A LEFT JOIN MST_INT_RATE_INFO B ON A.BASE_RULE_ID=INT_RATE_ID
LEFT JOIN (SELECT INT_RATE_ID ,INT_RATE_TYPE ,MAX(EFF_DATE) effDate FROM MST_INT_RATE_INFO
GROUP BY INT_RATE_ID,INT_RATE_TYPE ) C ON B.INT_RATE_ID=C.INT_RATE_ID AND B.INT_RATE_TYPE=C.INT_RATE_TYPE AND B.EFF_DATE=C.effDate WHERE A.INDEX_ID=#{indexId}
